import os
import base64
import tarfile
import io
import subprocess

print("=== Aggiornamento Song (maestro-studio) in corso ===")
app_dir = "/var/www/maestro-studio"
os.makedirs(app_dir, exist_ok=True)
os.chdir(app_dir)

b64_str = """"""

print("Decodifica archivio aggiornamento...")
tar_bytes = base64.b64decode(b64_str)

with tarfile.open(fileobj=io.BytesIO(tar_bytes), mode="r:gz") as tar:
    tar.extractall(path=".")

print("Verifica dipendenze (opzionale)...")
try:
    subprocess.run(["npm", "install", "--production", "--legacy-peer-deps"], check=False)
except Exception as e:
    print("Nota npm:", e)

print("Riavvio PM2...")
try:
    subprocess.run(["pm2", "restart", "maestro-studio", "--update-env"], check=True)
except Exception as e:
    print("PM2 restart fallito, avvio con node/tsx:", e)
    subprocess.run(["pm2", "start", "server.ts", "--name", "maestro-studio", "--interpreter", "npx", "--interpreter-args", "tsx"], check=True)

print("=== Aggiornamento completato con successo! ===")
